config_snippets.vite.config.ts:
import { sveltekit } from '@sveltejs/kit/vite';
import { defineConfig } from 'vite';
import adapter from '@sveltejs/adapter-cloudflare';
import tailwindcss from '@tailwindcss/vite';

export default defineConfig({
  plugins: [
    tailwindcss(),
    sveltekit({ adapter: adapter() }),
  ],
});
// NOTE: In SvelteKit 3 there is NO svelte.config.js. All config is passed to the
// sveltekit(...) Vite plugin. Options formerly under config.kit.* are now top-level
// plugin options (e.g. sveltekit({ adapter, paths, csrf, tracing, compilerOptions })).

config_snippets.wrangler.jsonc_minimal:
{
  "$schema": "./node_modules/wrangler/config-schema.json",
  "name": "strideguide",
  "compatibility_date": "2026-11-22",
  "assets": { "binding": "ASSETS" },
  "observability": { "enabled": true }
}
// adapter-cloudflare v9 generates the deploy-time config (main + assets.directory)
// at .svelte-kit/cloudflare/ and points .wrangler/deploy/config.json at it.
// You author bindings/name here; you do NOT need to hand-write main or assets.directory.
// Add a service binding here to call a separate Hono API Worker (see cross_origin_patterns).

config_snippets.wrangler.jsonc_autoconfig_variant:
{
  "main": ".svelte-kit/cloudflare/_worker.js",
  "assets": { "directory": ".svelte-kit/cloudflare", "binding": "ASSETS" }
}
// This is what `wrangler deploy` auto-detection generates for SvelteKit. Both shapes
// describe the same thing: a Worker script + Workers Static Assets (split config).

