config_snippets.pwa_withPwa_config:
import { defineConfig } from 'vite';
import { withPwa } from '@vite-pwa/sveltekit'; // v2.0.4 API
import adapter from '@sveltejs/adapter-cloudflare';
import tailwindcss from '@tailwindcss/vite';

export default defineConfig({
  plugins: [
    tailwindcss(),
    withPwa(
      // --- sveltekit() options ---
      { adapter: adapter() },
      // --- PWA options ---
      {
        registerType: 'autoUpdate',
        // 'generateSW' is the default (Workbox managed). Use 'buildSW' for a custom
        // service worker at src/service-worker.ts (formerly 'injectManifest').
        manifest: {
          name: 'Stride Guide',
          short_name: 'Stride',
          description: 'Stride Guide PWA',
          theme_color: '#0f172a',
          background_color: '#0f172a',
          display: 'standalone',
          start_url: '/',
          scope: '/',
          icons: [
            { src: '/pwa-192x192.png', sizes: '192x192', type: 'image/png' },
            { src: '/pwa-512x512.png', sizes: '512x512', type: 'image/png' },
            { src: '/pwa-maskable-512x512.png', sizes: '512x512', type: 'image/png', purpose: 'maskable' },
          ],
        },
        workbox: {
          // @vite-pwa/sveltekit already sets sensible globPatterns over
          // .svelte-kit/output (client/** and prerendered/**). Override only if needed.
          navigateFallback: '/',
        },
      }
    ),
  ],
});

config_snippets.hono_api_worker_cors:
import { Hono } from 'hono';
import { cors } from 'hono/cors';

const app = new Hono();
app.use('/api/*', cors({
  // Must be an EXPLICIT origin when credentials:true (never '*').
  origin: ['https://strideguide.example.com'],
  allowMethods: ['GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'OPTIONS'],
  allowHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 600,
}));
export default app;

config_snippets.hono_api_vite_config:
import { cloudflare } from '@cloudflare/vite-plugin';
import { defineConfig } from 'vite';

export default defineConfig({
  // Disable Vite's built-in CORS so it does not conflict with Hono's middleware.
  server: { cors: false },
  plugins: [cloudflare()],
});
